import json
from src.nodes.base import BaseNode
from src.runtime.scene_realization_review import get_scene_realization_review


class HouMCPSceneReviewNode(BaseNode):
    name = "hou_mcp_scene_review"
    category = "Houdini"

    def __init__(self):
        super().__init__()
        self.icon_path = "icons/houdini_icon.png"
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("assembly_result_json", "string", widget_type="text", default="{}")
        self.add_input("layout_plan_json", "string", widget_type="text", default="{}")
        self.add_output("production_ready", "bool")
        self.add_output("overall_score", "float")
        self.add_output("findings", "list")
        self.add_output("recommendations", "list")
        self.add_output("complexity_level", "string")
        self.add_output("review_json", "string")
        # [AUTO-GENERATED-PORTS-END]

    def _empty(self, error=""):
        report = {"production_ready": False, "overall_score": 0.0, "findings": [error] if error else [], "recommendations": [], "complexity_level": "unknown"}
        return {"production_ready": False, "overall_score": 0.0, "findings": [error] if error else [], "recommendations": [], "complexity_level": "unknown", "review_json": json.dumps(report, indent=2, default=str), "exec_out": True}

    async def execute(self, inputs):
        raw_assembly = (inputs.get("assembly_result_json") or "{}").strip() or "{}"
        raw_layout = (inputs.get("layout_plan_json") or "{}").strip() or "{}"

        try:
            assembly_result = json.loads(raw_assembly) if isinstance(raw_assembly, str) else raw_assembly
        except json.JSONDecodeError as exc:
            self.log_error(f"assembly_result_json is not valid JSON: {exc}")
            return self._empty(error=f"invalid assembly_result_json: {exc}")

        try:
            layout_plan = json.loads(raw_layout) if isinstance(raw_layout, str) else raw_layout
        except json.JSONDecodeError as exc:
            self.log_error(f"layout_plan_json is not valid JSON: {exc}")
            return self._empty(error=f"invalid layout_plan_json: {exc}")

        if not isinstance(assembly_result, dict) or not isinstance(layout_plan, dict):
            self.log_error("Inputs must be JSON objects.")
            return self._empty(error="inputs must be JSON objects")

        reviewer = get_scene_realization_review()
        try:
            review = reviewer.generate_realization_review(assembly_result, layout_plan)
        except Exception as exc:
            self.log_error(f"Scene review failed: {exc}")
            return self._empty(error=f"review failed: {exc}")

        production_ready = bool(review.get("production_ready", False))
        overall_score = float(review.get("overall_score", 0.0))
        findings = list(review.get("findings", []))
        recommendations = list(review.get("recommendations", []))

        complexity_level = "unknown"
        complexity_part = review.get("complexity", {})
        if isinstance(complexity_part, dict):
            complexity_level = complexity_part.get("complexity_level", "unknown")
        if complexity_level == "unknown":
            staging = assembly_result.get("staging_plan", {})
            if isinstance(staging, dict):
                cx = staging.get("complexity_estimate") or {}
                if isinstance(cx, dict):
                    complexity_level = cx.get("complexity_level", "unknown")

        status_label = "production_ready" if production_ready else "needs_improvement"
        self.log_info(f"Scene review: {status_label}, score={overall_score:.2f}, findings={len(findings)}, complexity={complexity_level}")

        report = {**review, "complexity_level": complexity_level}
        return {
            "production_ready": production_ready,
            "overall_score": overall_score,
            "findings": findings,
            "recommendations": recommendations,
            "complexity_level": complexity_level,
            "review_json": json.dumps(report, indent=2, default=str),
            "exec_out": True,
        }


def register_node():
    return HouMCPSceneReviewNode
